/* ============================================================
   Modelo 3D realista da abelha (GLB animado embutido em base64: nada para hospedar).
   Precisa de THREE.GLTFLoader (e, de preferência, THREE.SkeletonUtils) carregados.
   Se não existirem, a abelha continua com o modelo antigo.
   Crédito do modelo (Sketchfab): "Animated Bee" por sikoro, licença CC BY 4.0
   ============================================================ */
const AbelhaGLB = (() => {
  const B64 = '';
  const ESCALA = 1;               // comprimento do modelo = ESCALA × 'top' da abelha. Ajuste aqui.
  const COMPRIMENTO_MODELO = 22;  // comprimento original do GLB (não mexa)
  const OFFSET = { y: -3.5, z: -.42 };   // centraliza o corpo no ponto da abelha (unidades do GLB)
  const GIRO = Math.PI / 2;       // o modelo olha para +z; o corpo antigo olhava para +x

  let gltf = null, carregando = false;
  const fila = [], vivos = []; let P = null;   // P é criado só quando o THREE existir

  const bytes = () => { const s = atob(B64), u = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i); return u.buffer; };
  const falha = e => console.warn('Abelha (GLB):', e);

  // Cada abelha precisa do seu próprio esqueleto: clonamos com SkeletonUtils (ou lemos o arquivo de novo).
  function obter(cb) {
    if (!THREE.SkeletonUtils) return new THREE.GLTFLoader().parse(bytes(), '', g => cb(g.scene, g.animations), falha);
    const pronto = g => cb(THREE.SkeletonUtils.clone(g.scene), g.animations);
    if (gltf) return pronto(gltf);
    fila.push(pronto);
    if (carregando) return;
    carregando = true;
    new THREE.GLTFLoader().parse(bytes(), '', g => { gltf = g; fila.splice(0).forEach(f => f(g)); }, falha);
  }

  // Voando: animação 'hover' (asas batendo). Pousada: animação 'idle'. A troca é suave.
  let rodando = false, t0 = 0;
  function ciclo() {
    if (rodando) return; rodando = true; t0 = performance.now(); P = new THREE.Vector3();
    const passo = () => {
      requestAnimationFrame(passo);
      const t = performance.now(), dt = Math.min((t - t0) / 1000, .1); t0 = t;
      for (const v of vivos) {
        v.base.getWorldPosition(P);
        const vel = v.ini ? P.distanceTo(v.ult) / Math.max(dt, 1e-3) : 0;
        v.ult.copy(P); v.ini = true; v.vel = v.vel * .85 + vel * .15;
        v.w += ((v.vel > .15 * v.top ? 1 : 0) - v.w) * Math.min(1, dt * 8);
        if (v.voo) v.voo.setEffectiveWeight(v.w);
        if (v.par) v.par.setEffectiveWeight(1 - v.w);
        v.mixer.update(dt);
      }
    };
    passo();
  }

  function anexar(g, sp) {
    const rig = (g.userData && g.userData.rig) || g;   // entra no mesmo grupo do corpo antigo, para herdar a orientação
    obter((modelo, clips) => {
      const velhos = []; g.traverse(o => { if (o.isMesh) velhos.push(o); });
      velhos.forEach(o => o.parent && o.parent.remove(o));   // remove o corpo e as asas antigas de vez (só esconder pode ser desfeito pelo sistema)
      const top = (sp && sp.top) || .7, pivo = new THREE.Group(), giro = new THREE.Group();
      modelo.position.set(0, OFFSET.y, OFFSET.z);
      giro.rotation.y = GIRO; giro.add(modelo); pivo.add(giro);
      pivo.scale.setScalar(ESCALA * top / COMPRIMENTO_MODELO); rig.add(pivo);
      const solido = m => { m.transparent = false; m.opacity = 1; m.depthWrite = true; m.depthTest = true; m.blending = THREE.NormalBlending; m.alphaTest = 0; m.visible = true; m.side = THREE.DoubleSide; m.needsUpdate = true; };   // corpo sempre opaco
      modelo.traverse(o => { if (o.isMesh) { o.material = Array.isArray(o.material) ? o.material.map(m => m.clone()) : o.material.clone(); [].concat(o.material).forEach(solido); o.castShadow = true; o.frustumCulled = false; } });
      const mixer = new THREE.AnimationMixer(modelo), ac = n => { const c = clips.find(k => k.name.indexOf(n) >= 0); return c ? mixer.clipAction(c) : null; };
      const voo = ac('hover'), par = ac('idle');
      [voo, par].forEach(a => a && a.play());
      vivos.push({ base: g, mixer, voo, par, top, w: 1, ult: new THREE.Vector3(), ini: false, vel: 0 });
      ciclo();
    });
  }
  return { anexar };
})();

/* ============================================================
   Abelha: tudo sobre este animal fica nesta pasta.
   Seções: 1) dados e card · 2) ícone · 3) modelo 3D · 4) comportamento
   ============================================================ */
registerAnimal('abelha', {

  /* 1) DADOS: card informativo, quantidade inicial/máxima, cor do destaque e área de clique */
  data: {
      name: "Abelha",
      sci: "Apis mellifera",
      diet: "Nectarívora",
      role: "Polinizadora",
      habitat: "Canteiros de flores e bordas de mata.",
      desc: "Coleta néctar e pólen e, nesse trabalho, poliniza as flores, essencial para a reprodução de muitas plantas.",
      fact: "Para produzir 1 kg de mel, uma colônia precisa visitar milhões de flores.",
      qty: 10,
      max: 40,
      color: "#ffee58",
      hit: 0.7,
      hy: 0,
      top: 0.7,
      kind: "fly"
  },

  /* 2) ÍCONE (legenda e card) */
  icon: `<svg viewBox="0 0 48 48" aria-hidden="true"><ellipse cx="14" cy="14" rx="9" ry="6" fill="#cfe9ff" opacity=".9" transform="rotate(-30 14 14)"/><ellipse cx="34" cy="14" rx="9" ry="6" fill="#cfe9ff" opacity=".9" transform="rotate(30 34 14)"/><ellipse cx="24" cy="30" rx="12" ry="14" fill="#f1c40f"/><path d="M12 28c8 3 16 3 24 0v4c-8 3-16 3-24 0zM14 37c6 3 14 3 20 0l-1 3c-6 3-12 3-18 0z" fill="#1b1b1b"/><circle cx="24" cy="18" r="6" fill="#2b2b2b"/><circle cx="21.5" cy="17" r="1.4" fill="#fff"/><circle cx="26.5" cy="17" r="1.4" fill="#fff"/><path d="M21 13l-3-5M27 13l3-5" stroke="#2b2b2b" stroke-width="1.6" stroke-linecap="round"/></svg>`,

  flap: 40,       /* batidas de asa */
  hover: true,    /* leve vibração ao voar */

  /* 3) MODELO 3D: abelha realista e animada (GLB) sobre o corpo antigo, que continua guardando o rig usado pelo comportamento */
  build(sp) {
    const { E, CY, M } = Kit, u = sp.top, g = new THREE.Group(), rig = new THREE.Group(); g.add(rig);
    E(0xf1c40f, u * .42, u * .26, u * .26, 0, 0, 0, rig);
    E(0x1b1b1b, u * .12, u * .27, u * .27, -u * .05, 0, 0, rig); E(0x1b1b1b, u * .1, u * .26, u * .26, -u * .28, 0, 0, rig);
    E(0x2b2b2b, u * .2, u * .2, u * .2, u * .45, u * .03, 0, rig);
    [1, -1].forEach(s => E(0xffffff, u * .05, u * .06, u * .06, u * .55, u * .1, u * .14 * s, rig));
    g.userData = { wings: Kit.wings(rig, u, 0xcfe9ff, { glass: 1 }), head: null, rig };
    if (window.THREE && THREE.GLTFLoader) AbelhaGLB.anexar(g, sp);   // sem GLTFLoader: mantém o modelo antigo
    return g;
  },

  /* 4) COMPORTAMENTO: voa até uma flor, pousa e depois decola de novo. */
  decide(a, H) {
    if (Math.random() < .75) {
      const f = H.flowers[Math.floor(Math.random() * H.flowers.length)];
      return H.go(a, H.V(f.x, f.y + .12, f.z), 'land', H.r(3, 6));
    }
    H.go(a, H.flyPoint('abelha'), 'fly', 0);
  }
});
